#pragma once
#include "embedded-engine.h"
#include "../Source/PerformanceState.h"
#include <juce_audio_formats/juce_audio_formats.h>
#include <stdexcept>
inline void soloClickFadeCheck(zlplay::EmbeddedEngine* engine){using namespace juce;
    auto object=[](std::initializer_list<std::pair<const char*,var>> fields){auto* data=new DynamicObject();for(auto& field:fields)data->setProperty(field.first,field.second);return var(data);};
    auto file=File::getSpecialLocation(File::tempDirectory).getChildFile("zlplay-solo-fade-"+Uuid().toString()+".wav");struct Cleanup{File file;~Cleanup(){file.deleteFile();}}cleanup{file};AudioBuffer<float> pcm(2,44100*4);for(int channel=0;channel<2;++channel)FloatVectorOperations::fill(pcm.getWritePointer(channel),.25f,pcm.getNumSamples());WavAudioFormat wav;std::unique_ptr<AudioFormatWriter> writer(wav.createWriterFor(new FileOutputStream(file),44100,2,16,{},0));if(!writer||!writer->writeFromAudioSampleBuffer(pcm,0,pcm.getNumSamples()))throw std::runtime_error("fade fixture write failed");writer.reset();
    auto call=[&](var request){return zlplay::engineCommand(engine,request);};auto item=object({{"path",file.getFullPathName()},{"position",0},{"offset",0},{"length",4},{"rate",1}});auto music=object({{"items",Array<var>{item}},{"gain",1},{"pitch",0},{"bus","VS"},{"effectId","track:0"},{"outputLeft",0},{"outputRight",1}});auto click=object({{"items",Array<var>{item}},{"gain",1},{"pitch",0},{"bus","Click"},{"effectId","track:1"},{"outputLeft",2},{"outputRight",-1}});call(object({{"op","load"},{"offline",true},{"sampleRate",44100},{"duration",4},{"tracks",Array<var>{music,click}}}));
    auto capture=[&](int frames){return call(object({{"op","renderTest"},{"frames",frames},{"channels",3},{"capture",true},{"position",0}}))["samples"];};auto baseline=capture(1);double amplitude=double(baseline[0]),clickAmplitude=double(baseline[2]);if(amplitude<=0||clickAmplitude<=0)throw std::runtime_error("fade fixture silent");
    for(int target:{0,1}){auto mix=Array<var>{object({{"gain",target},{"pitch",0},{"bus","VS"},{"outputLeft",0},{"outputRight",1}}),object({{"gain",1},{"pitch",0},{"bus","Click"},{"outputLeft",2},{"outputRight",-1}})};call(object({{"op","mix"},{"master",1},{"fadeSeconds",1.5},{"mix",mix}}));call(object({{"op","mix"},{"master",1},{"mix",mix}}));auto samples=capture(88200);for(int frame:{0,16537,33074,66149,80000}){double fraction=jmin(1.,(frame+1)/66150.);double expected=target==0?1-fraction:fraction;if(std::abs(double(samples[frame*3])/amplitude-expected)>.00004)throw std::runtime_error((String("1.5 second solo Click fade interrupted: target=")+String(target)+" frame="+String(frame)+" actual="+String(double(samples[frame*3])/amplitude,8)+" expected="+String(expected,8)+" amplitude="+String(amplitude,8)).toStdString());if(std::abs(double(samples[frame*3+2])-clickAmplitude)>.00004)throw std::runtime_error("project Click must remain audible during music fade");}}
    auto measured=call(object({{"op","meters"}}));auto roleLevels=performance::specialMeterLevels(measured,Array<int>{1,2});if(roleLevels.guide<.2f||roleLevels.click<.2f||performance::meterPeak(measured["click"])>.0001f)throw std::runtime_error("imported Guide/Click meters must display native track peaks without native Click");

}
